#ANIM_FRAME_MAX# #ANIM_FRAME_MIN# - (O:ANIM_INTERVAL) / (>O:ANIM_POS_INC)
(O:ANIM_TARGET_POS) (O:ANIM_CUR_POS) - abs (O:ANIM_POS_INC) < if{
    (O:ANIM_TARGET_POS) (>O:ANIM_CUR_POS)
    (O:ANIM_CUR_POS) #ANIM_FRAME_MIN# > if{
        #ANIM_FRAME_REST# (>O:ANIM_TARGET_POS)
        #ONANIMFINISHED#
    }
} els{
    (O:ANIM_TARGET_POS) (O:ANIM_CUR_POS) > if{
        (O:ANIM_CUR_POS) (O:ANIM_POS_INC) + (>O:ANIM_CUR_POS)
    } els{
        (O:ANIM_CUR_POS) (O:ANIM_POS_INC) - (>O:ANIM_CUR_POS)
    }
}
(O:ANIM_CUR_POS) #ANIM_FRAME_MIN# max (>O:ANIM_CUR_POS)
(O:ANIM_CUR_POS) #ANIM_FRAME_MAX# min (>O:ANIM_CUR_POS)                
(O:ANIM_CUR_POS)

