Case.SET_SIMVAR_FROM_POSITION:
(* SwimVar pos is handled there for interactions + in update for automatic state switches *)
-1 sp0
(A:SIM ON GROUND, Bool) if{
	(L:XMLVAR_Autobrake_Level_Armed) #AUTOBRAKE_OFF# == if{
		#AUTOBRAKE_OFF# sp0
	} els{
		#AUTOBRAKE_RTO# sp0
	}
} els{
	(L:XMLVAR_Autobrake_Level_Armed) sp0
}
l0 -1 != l0 (A:AUTO BRAKE SWITCH CB, Enum) != and if{
	l0 (>K:SET_AUTOBRAKE_CONTROL)
}

Case.SET_STATE_EXTERNAL:
#TEST_DISABLED# if{ 
	0 (>O:HANDLING_Autobrake_Level_#ID#_Position)
} els{
	p0 if{ 
		#AUTOBRAKE_LEVEL# (>L:XMLVAR_Autobrake_Level_Armed) 
	} els{ 
		(L:XMLVAR_Autobrake_Level_Armed) #AUTOBRAKE_LEVEL# == if{
			#AUTOBRAKE_OFF# (>L:XMLVAR_Autobrake_Level_Armed)
		} 
	}
}
#SET_SIMVAR_FROM_POSITION#

Condition.COMP_UPDATE_CODE:
(* Handle disarming after landing gear up *)
(O:_Countdown_Disable_Autobrake) 0 > if{
	(O:_Countdown_Disable_Autobrake) 1 - (>O:_Countdown_Disable_Autobrake)
	(O:_Countdown_Disable_Autobrake) 0 <= if{
		1 (>K:SET_AUTOBRAKE_CONTROL)
		#AUTOBRAKE_OFF# (>L:XMLVAR_Autobrake_Level_Armed)
	}
}
(L:XMLVAR_Autobrake_Level_Armed) #AUTOBRAKE_OFF# > if{
	(A:GEAR HANDLE POSITION, Bool) s0 (O:_Gear_Position) != sp1 l0 (>O:_Gear_Position)
	l1 l0 ! and if{ 
		#AUTODISABLE_COUNTDOWN# (>O:_Countdown_Disable_Autobrake)
	}
}

Case.ENUM_VAL_TO_POS_EXTERNAL:
l1 if{ #POS_DISARM# sp2 g2 }
els{
	l0 0 == if{ #POS_RTO# sp2 g2 }
	l0 1 == if{ #POS_OFF# sp2 g2 }
	l0 2 == if{ #POS_1# sp2 g2 }
	l0 3 == if{ #POS_2# sp2 g2 }
	l0 4 == if{ #POS_3# sp2 g2 }
	l0 5 == if{ #POS_4# sp2 g2 }
	l0 6 == if{ #POS_MAX_AUTO# sp2 g2 }
} :2 l2

Condition.UPDATE_ELT_STATE:
(A:ELT ACTIVATED, Bool) if{
	#ELT_ON# (>#ELT_SCOPE#:#ELT_VAR#)
} els{
	#ELT_ON# (#ELT_SCOPE#:#ELT_VAR#) == if{
		#ELT_ARM# (>#ELT_SCOPE#:#ELT_VAR#)
	}
	#ELT_TEST# (#ELT_SCOPE#:#ELT_VAR#) == if{
		(E:SIMULATION TIME, second) (L:XMLVAR_ELT_TEST_TIME) - #ELT_TEST_DURATION# > if{
			#ELT_ARM# (>#ELT_SCOPE#:#ELT_VAR#)
		}
	}
}
